pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 minSum, uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(depositAmount >= minSum);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(!reverted &&
            balAfter == balBefore - collectAmount &&
            cBalAfter == cBalBefore - collectAmount);
    }

    function testFuzz_run(uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        _run(minSum, depositAmount, collectAmount);
    }

    receive() external payable {}
}
